import * as React from 'react';
import Button from '@mui/material/Button';
import Menu, { MenuProps } from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import Divider from '@mui/material/Divider';
import { ProductList } from '../TestList';
import { MenuBarProps, ProductCategories } from '../GlobalInterfaces';
import Swal from 'sweetalert2'
import Stack from '@mui/material/Stack';
import PopupState, { bindTrigger, bindMenu } from 'material-ui-popup-state';
import IconButton from '@mui/material/IconButton';
import KeyboardDoubleArrowLeftIcon from '@mui/icons-material/KeyboardDoubleArrowLeft';
import { useRef } from 'react';
import KeyboardDoubleArrowRightIcon from '@mui/icons-material/KeyboardDoubleArrowRight';
export default function CustomizedMenus({props}: {props: MenuBarProps} ) {

  const SCROLL_BAR_WIDTH : number = 51.5

  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  
  const showSwal = () => {
    Swal.fire({
        title: "Max number of products reached.",
        text: "Please remove a product",
        icon: "warning",
        confirmButtonColor: "#3085d6",
        confirmButtonText: "Okay",
    });
  }



  const ref = useRef<HTMLInputElement>(null);
  const scroll = (scrollOffset: number) => {
    let scrollAmount : number = document.documentElement.clientWidth * (SCROLL_BAR_WIDTH /100) * scrollOffset
    console.log(scrollAmount)
    if (ref.current != null) {
      ref.current.scrollTo({
        left: ref.current.scrollLeft + scrollAmount,
        behavior: "smooth",
      })
    }
  };

  const addMe = (value: string) =>{
    if (props.currentProducts.length > 30) {
      setAnchorEl(null);
      showSwal()
    } 
      props.setCurrentProducts(props.currentProducts.concat([value]));
  }
  
  function DropDown({categories}: {categories: ProductCategories} ) {
    return (
      <div>
        <PopupState variant="popover" popupId="demo-popup-menu">
          {(popupState) => (
            <React.Fragment>
              <Button sx={{
                overflow:'hidden',
                marginLeft: 'auto',
                marginRight: '0',
                marginTop:'.5vh',
                width:'10vw',
                borderRadius: '10px',
                height:'80%'
              }}
                variant="contained" {...bindTrigger(popupState)}>
                {categories.category}
              </Button>
              <Menu {...bindMenu(popupState)}>
              {categories.productList.map((productList:string, index:number) => (
                <MenuItem onClick={() => addMe(productList)} >
                  <div style={{width: '9vw', overflow: 'hidden'}} className="productText">
                    {productList}
                    <Divider/>

                  </div>
                </MenuItem>
              ))}
              </Menu>
            </React.Fragment>
          )}
        </PopupState>
      </div>     
    )
  }

  return (
    <div
    >
      <Stack 
      sx={{
        marginLeft: '22.5vw',
        marginTop:'2vh',
        minWidth: 0,
        height:"5vh",
        marginRight: '0',
        maxWidth:'70vw',
        overflow:'hidden',
        borderRadius: '10px',
        background:'white'
      }}
        direction="row"
        spacing={'0px'}>
        
        <IconButton  sx={{width: '1.5vw'}}aria-label="reverse" onClick={() => scroll(-1)}>
          <KeyboardDoubleArrowLeftIcon />
        </IconButton>
        <Stack 
      ref={ref}
      sx={{
        marginLeft: 'auto',
        marginTop:'2vh',
        minWidth: 0,
        height:"5vh",
        marginRight: '0',
        width:'51vw',
        overflow:'hidden',
        borderRadius: '10px',
        background:'white'
      }}
        direction="row"
        spacing={'.25vw'}>
        {ProductList.map((value:ProductCategories, index:number) => (
          <DropDown categories={ value }/>
        ))}
      </Stack>


        <IconButton sx={{width: '1.5vw'}} aria-label="add" onClick={() => scroll(1)}>
          <KeyboardDoubleArrowRightIcon />
        </IconButton>
      </Stack>
    </div>
  );
} 